import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = config.name || 'collection-card-3';

  // Load ceramic grain texture
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Atlas region dimensions: 512×320 pixels
  // Aspect ratio: 1.6
  const sceneHeight = 0.75;
  const sceneWidth = sceneHeight * (512 / 320);

  // Create billboard plane geometry
  const geometry = new THREE.PlaneGeometry(sceneWidth, sceneHeight);

  // Create material with TSL texture node
  const colorNode = textureNode(texture);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create sprite mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  mesh.position.set(3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  group.add(mesh);

  // Setup handlers container and cleanup
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
